parameters.jsCode:
const input=$json??{};
const state=input.activeMilestoneState??input.milestoneState??{};
const evidence=input.evidence??input.closingEvidence??{};
const milestones=Array.isArray(input.milestones)?input.milestones:[];
const required=Array.isArray(input.requiredEvidence)?input.requiredEvidence:[];
const supplied=Array.isArray(input.suppliedEvidence)?input.suppliedEvidence:[];
const suppliedSet=new Set(supplied.map(x=>String(x).toLowerCase()));
const evidenceMap=Array.isArray(evidence.items)?evidence.items:evidence;
const normalizedEvidence=Array.isArray(evidenceMap)?evidenceMap.map(x=>({type:String(x.type??x.name??'').toLowerCase(),verified:Boolean(x.verified??x.confirmed??false),id:x.id??null})):[];

const requiredResults=required.map(r=>{
  const key=String(r.type??r.name??r).toLowerCase();
  const found=normalizedEvidence.find(e=>e.type===key&&e.verified)||suppliedSet.has(key);
  return {type:key,verified:found};
});
const missingEvidence=requiredResults.filter(x=>!x.verified).map(x=>x.type);

const incompleteMilestones=milestones.filter(m=>!['completed','complete','closed'].includes(String(m.status??'pending').toLowerCase())).map(m=>m.sequence??m.id??null);
const executionState=String(state.execution_state??input.executionState??'').toLowerCase();
const blockers=Array.isArray(input.blockers)?input.blockers.filter(Boolean):[];

let status='reconciled';
if(blockers.length) status='blocked';
else if(missingEvidence.length||incompleteMilestones.length) status='reconciliation_gap';
else if(executionState && !['active','launched_pending_milestone_confirmation','completed','closed'].includes(executionState)) status='attention_required';

const route=status==='blocked'?'WF-126':status==='reconciliation_gap'?'WF-155':status==='attention_required'?'WF-155':'WF-137';

return [{json:{
  ...input,
  workflow:'WF-181',
  evidence_reconciliation:{
    status,
    required_evidence_count:requiredResults.length,
    verified_evidence_count:requiredResults.filter(x=>x.verified).length,
    missing_evidence:missingEvidence,
    incomplete_milestones:incompleteMilestones,
    blockers,
    execution_state:executionState||null
  },
  routing:{
    next_workflow:route,
    reason:status,
    requires_human_review:status==='blocked'
  },
  audit:{
    event:'closing_evidence_reconciliation_evaluated',
    status,
    missing_evidence_count:missingEvidence.length,
    incomplete_milestone_count:incompleteMilestones.length
  }
}}];

